// Photo asset "trash-can" — added by the builder (their own real, local image).
// Use it in any page with:
//   <script src="./assets/trash-can.js"></script>
//   <img data-asset="trash-can" alt="describe the photo">
window.ASSETS = Object.assign(window.ASSETS || {}, { "trash-can": "data:image/jpeg;base64," });
(function () {
  function apply() { document.querySelectorAll('img[data-asset="trash-can"]').forEach(function (img) { img.src = window.ASSETS["trash-can"]; }); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply); else apply();
})();
